//
// 우선순위:
//   1) localStorage["agentlas.locale"] (사용자 override)
//   2) IPC app.getLocale() → macOS "시스템 설정 > 언어 및 지역" 1순위
//   3) "en" fallback
//
// Codex / Claude Desktop과 동일한 패턴 (별도 첫 화면 언어 선택 안 함).
