    "one.feat.slide.work.body": "평소처럼 말하면 One이 일을 나누어 전문 에이전트와 팀(로컬·내 Cloud·Hub)에 맡기고, Claude Code·Codex·Gemini·Antigravity 같은 내 CLI를 직접 굴립니다. 무엇을 탐색하고 실행하고 편집했는지는 턴마다 대화에 남고, 자세히 보고 싶을 때만 Work를 엽니다.",
