    "one.feat.slide.mobile.body": "목표를 맡기면 끝날 때까지 이어서 일하고, 승인이 필요한 순간에만 돌아옵니다. Mobile에서는 같은 진행과 결정을 그대로 이어받고, Desktop 연결이 끊기면 진행된 것처럼 보여주지 않습니다.",
