    "one.feat.slide.proof.body": "일에서 배운 것을 기억과 재사용 가능한 스킬로 남기고, 자주 쓰는 팀과 취향을 알맞은 때 다시 꺼내 씁니다. 무엇이 달라졌는지는 결과 뒤에 증거와 함께 알려줍니다.",
