    "one.shell.system_prompt.auto_recover": "직전 시도는 다음 이유로 끝까지 가지 못했습니다: {reason}\n\n같은 방법을 그대로 반복하지 마세요. 무엇이 막혔는지 먼저 판단하고, 다른 경로·다른 도구·더 작은 단계로 나눠서 목표를 끝까지 완성하세요. 사용자가 연결한 프로젝트 파일이나 설정 안에 원인이 있고 현재 권한으로 안전하게 되돌릴 수 있다면 직접 고치고 검증하세요. 설치된 Agentlas 앱이나 서명된 런타임 자체는 변경하지 마세요. 한 방법이 막히면 우회할 방법을 스스로 찾아 계속하세요. 사람의 결정이나 새 권한이 반드시 필요한 경우에만 멈추고, 그때는 무엇을 결정해야 하는지 한 가지만 물어보세요. 그 밖에는 완성된 결과만 보여주세요.",
    "one.shell.system_prompt.clarify_decision": "다음 사용자 결정은 아직 실행하거나 승인하지 마세요. One 안에서 필요한 정보만 보완해야 합니다. 사용자가 한 번에 답할 수 있도록 대상, 비용, 되돌리기 중 빠진 핵심 한 가지만 짧고 자연스럽게 질문하세요. Work로 보내거나 내부 코드·오류·ID를 보여주지 마세요. 현재 결정: {question}. 현재 선택지: {options}",
