    // One · one.feat
    "one.feat.slide.briefing.title": "One is a personal agent that knows you.",
    "one.feat.slide.briefing.body": "It builds a memory map from the preferences, principles, and project context you keep, and reasons on top of it. It spots important changes and prepares the next decision, and asks only at boundaries such as file changes or sending things outside.",
    "one.feat.slide.work.title": "Say it once. One commands many agents.",
    "one.feat.slide.work.body": "Talk to One normally; it splits the work across specialist agents and teams (local, your Cloud, the Hub) and drives your own CLIs — Claude Code, Codex, Gemini, Antigravity. What it explored, ran, and edited stays in the conversation turn by turn; open Work only when you want the details.",
    "one.feat.slide.mobile.title": "It works while you are away and brings back only decisions.",
    "one.feat.slide.mobile.body": "Hand it a goal and it keeps going until it is done, returning only when something needs your approval. Mobile picks up the same progress and decisions, and never pretends work continued while Desktop was disconnected.",
    "one.feat.slide.proof.title": "The more you use it, the more it fits you.",
    "one.feat.slide.proof.body": "What it learns from work becomes memory and reusable skills; it brings back the teams and preferences you rely on at the right moment, and shows what changed after the result — with evidence.",
