type DictKey = keyof typeof dict.ko;

interface I18nValue {
  locale: Locale;
  /** undefined = system, "ko" / "en" = user override */
  pref: LocalePref;
  setPref: (p: LocalePref) => void;
  t: (key: DictKey, vars?: Record<string, string | number>) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

// ── 비-훅 locale 스냅샷 ──────────────────────────────────
// 모듈 스토어·이벤트 핸들러 등 React 컴포넌트 밖에서 현재 표시 언어를 읽기 위한 접근자.
// I18nProvider가 locale이 바뀔 때마다 갱신한다(단일 출처). 앱은 항상 Provider 아래에서
// 상호작용하므로, 사용자 트리거 시점엔 이미 확정된 값이 들어 있다. SSR 기본과 동일한 "en"으로 시작.
let _localeSnapshot: Locale = "en";
/** 컴포넌트 밖에서 현재 표시 언어를 읽는다(useT 훅을 못 쓰는 스토어/핸들러용). */
export function currentLocale(): Locale {
  return _localeSnapshot;
}

function resolveSystem(localeStr: string): Locale {
  // macOS는 "ko-KR" / "ja-JP" / "en-US" 같은 BCP47 반환.
  return localeStr.toLowerCase().startsWith("ko") ? "ko" : "en";
}

function interpolate(text: string, vars?: Record<string, string | number>): string {
  if (!vars) return text;
  return text.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? `{${k}}`));
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [pref, setPrefState] = useState<LocalePref>("en");
  const [locale, setLocaleState] = useState<Locale>("en"); // English is the product default; Korean remains an explicit choice.
  const [_ready, setReady] = useState(false);

  // 초기 부팅: 사용자 override 또는 OS locale
  useEffect(() => {
    void (async () => {
      /*
       * ★ 저장된 선택이 없으면 **보는 사람의 언어를 따른다** (2026-08-24 수리).
       *
       * 여기 기본값이 "en" 이었다. 그런데 바로 아래에서 `stored` 가 "ko" 또는 "en" 이면
       * 곧바로 빠져나가므로, **저장된 선택이 없는 사람에게는 아래의 시스템 언어 조회가
       * 한 번도 실행되지 않았다.** 결과: 한국어 사용자가 처음 들어오면 화면이 전부 영어이고,
       * 설정에서 직접 고르기 전에는 그대로다. 나머지 사이트는 한국어인데 주력 제품만 영어였다.
       *
       * 이 파일 머리에 적힌 규칙이 원래 "저장값 → 시스템 언어 → 영어" 였다. 코드가 그
       * 규칙과 어긋나 있었고, 여기서 규칙대로 되돌린다.
       */
      let stored: LocalePref = "system";
      try {
        const raw = window.localStorage.getItem(STORAGE_KEY);
        if (raw === "ko" || raw === "en") stored = raw;
      } catch {
        // ignore
      }
      setPrefState(stored);

      if (stored === "ko" || stored === "en") {
        setLocaleState(stored);
        setReady(true);
        return;
      }
      // System — IPC로 OS 로케일 조회
      const api = ipc();
      if (api?.app?.getLocale) {
        try {
          const sys = await api.app.getLocale();
          setLocaleState(resolveSystem(sys));
        } catch {
          setLocaleState("en");
        }
      } else {
        // 브라우저 dev — navigator.language fallback
        const nav = (typeof navigator !== "undefined" ? navigator.language : "en") ?? "en";
        setLocaleState(resolveSystem(nav));
      }
      setReady(true);
    })();
  }, []);

  // 표시 언어가 바뀔 때마다 (1) 비-훅 스냅샷을 갱신하고 (2) 네이티브 macOS 메뉴바도 같은 언어로 다시 그린다.
  useEffect(() => {
    _localeSnapshot = locale;
    const api = ipc();
    void api?.menu?.setLocale?.(locale);
  }, [locale]);

  const setPref = useCallback((p: LocalePref) => {
    try {
      if (p === "system") window.localStorage.removeItem(STORAGE_KEY);
      else window.localStorage.setItem(STORAGE_KEY, p);
    } catch {
      // ignore
    }
    setPrefState(p);
    if (p === "ko" || p === "en") {
      setLocaleState(p);
    } else {
      const api = ipc();
      if (api?.app?.getLocale) {
        void api.app.getLocale().then((sys) => setLocaleState(resolveSystem(sys)));
      }
    }
  }, []);

  const t = useCallback(
    (key: DictKey, vars?: Record<string, string | number>) => {
      // per-key 폴백은 en(기본 언어). 어떤 키가 현재 로케일에 없으면 영어로 떨어지고,
      // en에도 없을 때만 raw 키를 노출한다 — 영어 사용자에게 한국어가 새는 걸 막는다.
      const raw =
        (dict[locale] as Record<string, string>)[key] ??
        (dict.en as Record<string, string>)[key] ??
        key;
      return interpolate(raw, vars);
    },
    [locale],
  );

  // locale이 확정(_ready)되기 전에는 텍스트를 그리지 않는다 — OS 언어를 IPC로 받기 전에는
  // SSR 기본값 "ko"로 먼저 그려져, 영어 시스템에서 ko→en 깜빡임이 생기거나 텍스트 없는
  // 순간이 (다크 테마에선 --paper 값이 짙어) 검은 화면처럼 보이던 문제를 막는다.
  // 빈 자리는 현재 테마색(var(--paper))으로 채워 라이트/다크 어느 쪽도 검게 보이지 않게 한다.
  // value 객체 리터럴이 렌더마다 새 참조면, 이 프로바이더에 상태가 하나라도 늘어나는
  // 순간 앱 전체의 useT() 소비자가 전부 리렌더된다. 지금 참조를 고정해 둔다.
  const contextValue = useMemo(() => ({ locale, pref, setPref, t }), [locale, pref, setPref, t]);
  return (
    <I18nContext.Provider value={contextValue}>
      {_ready ? children : <div style={{ minHeight: "100vh", background: "var(--paper)" }} aria-hidden />}
    </I18nContext.Provider>
  );
}

export function useT(): I18nValue {
  const ctx = useContext(I18nContext);
  if (!ctx) {
    // Provider 외부에서 호출 (next/error 페이지 등) — 기본 언어 en으로 폴백.
    return {
      locale: "en",
      pref: "system",
      setPref: () => {},
      t: (k, v) => interpolate((dict.en as Record<string, string>)[k] ?? k, v),
    };
  }
  return ctx;
}

/** useT()의 conversation-locale 변형. One의 대화형 chrome은 이 스레드의 언어
 *  (one-conversation-locale의 inferOneConversationLocale)를 따르며, 이는 useT()가
 *  노출하는 앱-환경설정 locale과 다를 수 있다. tFor는 그 표면들이 **같은 카탈로그**를
 *  명시적 locale로 인덱싱해 읽게 해준다. 키 단위로 en → raw key 순으로 폴백한다.
 *  컴포넌트 밖(스토어/메인 IPC 핸들러)에서도 쓸 수 있다. */
export function tFor(locale: Locale, key: DictKey, vars?: Record<string, string | number>): string {
  const raw =
    (dict[locale] as Record<string, string>)[key] ??
    (dict.en as Record<string, string>)[key] ??
    key;
  return interpolate(raw, vars);
}

/** 다국어 시드 객체에서 현재 locale에 맞는 표시 이름·태그라인을 뽑는 헬퍼.
 *  영어 사용자에게 한국어가 새지 않게 하는 통일 진입점. */
export function pickLocalized<T extends { name: string; nameEn?: string; tagline?: string; taglineEn?: string }>(
  item: T,
  locale: Locale,
): { name: string; tagline: string } {
  if (locale === "en") {
    return {
      name: item.nameEn?.trim() || item.name,
      tagline: item.taglineEn?.trim() || item.tagline || "",
    };
  }
  return { name: item.name, tagline: item.tagline ?? "" };
}
